57	    test('a listener that subscribes before any call still immediately '
58	        'sees true, not nothing until the first emission (Stream.multi '
59	        'replay)', () async {
60	      final value = await repository.biometricEnabledStream.first;
61	
62	      expect(value, isTrue);
63	    });
64	  });
