208	      when(() => mockRemoteDataSource.updateBiometricEnabled(false)).thenAnswer(
209	        (_) async =>
210	            right(const AccountSettingsDto(biometricEnabled: false)),
211	      );
212	
213	      await repository.dispose();
214	
215	      final result = await repository.setBiometricEnabled(false);
216	
217	      expect(result.isRight(), isTrue);
218	      // Both the optimistic flip and the (here, unreached) revert path
219	      // attempt to emit on an already-closed controller — a silent no-op,
220	      // same as fetchBiometricEnabled()'s own case above.
221	      expect(repository.currentBiometricEnabled, isTrue);
222	    });
223	  });
