225	  group('overlapping calls — only the latest one\'s result ever applies '
226	      '(review finding)', () {
227	    test('a fetchBiometricEnabled() that resolves after a later '
228	        'setBiometricEnabled() has already started is discarded as stale '
229	        '— it must not clobber the newer optimistic flip', () async {
230	      final fetchCompleter = Completer<Either<Failure, AccountSettingsDto>>();
231	      when(() => mockRemoteDataSource.fetchSettings())
232	          .thenAnswer((_) => fetchCompleter.future);
233	      when(() => mockRemoteDataSource.updateBiometricEnabled(false)).thenAnswer(
234	        (_) async =>
