238	      // The boot fetch starts first and is held pending...
239	      final fetchFuture = repository.fetchBiometricEnabled();
240	
241	      // ...then a toggle starts and completes while the fetch is still in
242	      // flight, flipping (and confirming) the value to false.
243	      final toggleResult = await repository.setBiometricEnabled(false);
244	      expect(toggleResult.isRight(), isTrue);
245	      expect(repository.currentBiometricEnabled, isFalse);
246	
247	      // The stale fetch now resolves with a DIFFERENT value (true) — if
248	      // it were applied, it would wrongly stomp the toggle's already-
249	      // confirmed false.
250	      fetchCompleter.complete(
