252	      );
253	      final fetchResult = await fetchFuture;
254	
255	      expect(repository.currentBiometricEnabled, isFalse);
256	      // Review finding: a stale fetch must not report success either —
257	      // its own result was discarded, mirroring `setBiometricEnabled`'s
