267	      when(() => mockRemoteDataSource.updateBiometricEnabled(false))
268	          .thenAnswer((_) => firstPatchCompleter.future);
269	      when(() => mockRemoteDataSource.updateBiometricEnabled(true)).thenAnswer(
270	        (_) async => right(const AccountSettingsDto(biometricEnabled: true)),
271	      );
272	
273	      // First toggle (to false) starts and is held pending.
274	      final firstResultFuture = repository.setBiometricEnabled(false);
275	      expect(repository.currentBiometricEnabled, isFalse);
276	
277	      // A second, overlapping toggle (back to true) starts and completes
278	      // first — this is the newest call, so it owns the final value.
279	      final secondResult = await repository.setBiometricEnabled(true);
280	      expect(secondResult.isRight(), isTrue);
281	      expect(repository.currentBiometricEnabled, isTrue);
282	
283	      // The first (now superseded) call's PATCH finally resolves — as a
284	      // failure, which would otherwise revert back to its own captured
285	      // "previous" value (true, the value before IT started). Even though
286	      // that happens to match here, the call must be recognized as
287	      // superseded and return `Left` rather than silently succeeding on a
288	      // value it no longer owns.
289	      firstPatchCompleter.complete(
290	        left(const Failure.networkTimeout(message: 'fake: too slow')),
291	      );
292	      final firstResult = await firstResultFuture;
293	
294	      expect(firstResult.isLeft(), isTrue);
295	      // The second call's confirmed value must still be in effect,
296	      // untouched by the first (superseded) call's own resolution.
297	      expect(repository.currentBiometricEnabled, isTrue);
298	    });
299	  });
