  Future<BoxBase<E>> _openBox<E>(
    String name,
    bool lazy,
    HiveCipher? cipher,
    int? keyCrc,
    KeyComparator comparator,
    CompactionStrategy compaction,
    bool recovery,
    String? path,
    Uint8List? bytes,
    String? collection,
  ) async {
    assert(path == null || bytes == null);
    assert(
      name.length <= 255 && name.isAscii,
      'Box names need to be ASCII Strings with a max length of 255.',

    'Box names need to be ASCII Strings with a max length of 255.',
  );
  typedMapOrIterableCheck<E>();

  name = name.toLowerCase();
  if (isBoxOpen(name)) {
    if (lazy) {
      return lazyBox(name);
    } else {
      return box(name);
    }
  } else {
    if (_openingBoxes.containsKey(name)) {
      await _openingBoxes[name];
      if (lazy) {
        return lazyBox(name);
      } else {
        return box(name);
      }
    }

    final completer = Completer();
    _openingBoxes[name] = completer.future;

    BoxBaseImpl<E>? newBox;
    try {
      StorageBackend backend;
      if (bytes != null) {
        backend = StorageBackendMemory(bytes, cipher, keyCrc);
      } else {
        backend = await _manager.open(
          name,
          path ?? homePath,
          recovery,
          cipher,
          keyCrc,
          collection,
        );
      }

      if (lazy) {
        newBox = LazyBoxImpl<E>(
          this,
          name,
          comparator,
          compaction,
          backend,
          isolated: _isolated,
        );
      } else {
        newBox = BoxImpl<E>(
          this,
          name,
          comparator,
          compaction,
          backend,
          isolated: _isolated,
        );
      }

      await newBox.initialize();
      _boxes[name] = newBox;

      completer.complete();

      if (!_isolated) HiveConnect.registerBox(newBox);

      return newBox;
    } catch (error, stackTrace) {
      try {
        await newBox?.close();
      } catch (_) {
        // Keep the original open error.
      }
      completer.completeError(error, stackTrace);
      rethrow;
    } finally {
      _openingBoxes.remove(name)?.ignore();
    }
  }
