import 'package:flutter_secure_storage/flutter_secure_storage.dart';
import 'package:local_auth/local_auth.dart';

import '../../core/di/injection_container.dart';
import 'data/repositories/vault_repository_impl.dart';
import 'domain/repositories/vault_repository.dart';

/// Registers the `vault` feature into the project's single `get_it`
/// instance (`sl`) — mirrors `features/auth/auth_injection.dart`'s pattern.
/// Called from `setupCoreDependencies()` right after `registerAuthFeature()`
/// (Code Map).
void registerVaultFeature() {
  sl.registerLazySingleton<LocalAuthentication>(() => LocalAuthentication());

  // The epic's ONE new DI-singleton access point for device-level access
  // (AD-14) — registered as a singleton so every consumer (the `/vault`
  // lock screen; `core/navigation/app_router.dart`'s redirect; `main.dart`)
  // shares the same `statusStream`, not a fresh instance each. `dispose:`
  // wires `VaultRepository.dispose()` into `get_it`'s own reset lifecycle,
  // so `resetCoreDependencies()` (`sl.reset()`) closes its
  // `StreamController` instead of leaking one on every test teardown.
  sl.registerLazySingleton<VaultRepository>(
    () => VaultRepositoryImpl(
      localAuthentication: sl<LocalAuthentication>(),
      // Already registered by `setupCoreDependencies()` (Code Map) — the
      // same singleton `SecureStorageAccessTokenProvider` uses for the
      // access/refresh tokens, now also holding the vault PIN (Story 2.2)
      // under its own distinct key.
      secureStorage: sl<FlutterSecureStorage>(),
    ),
    dispose: (repository) => repository.dispose(),
  );
}

import 'package:hive_ce/src/box/box_base.dart';

/// Boxes contain all of your data. In the browser, each box has its own
/// IndexedDB database. On all other platforms, each Box is stored in a
/// separate file in the Hive home directory.
///
/// Write operations are asynchronous but the new values are immediately
/// available. The returned `Future` finishes when the change is written to
/// the backend. If the process is killed before then, the write can be lost.
/// See [flush].
/// If this operation fails, the changes are being reverted.
///
/// Read operations for normal boxes are synchronous (the entries are in
/// memory). Lazy boxes have asynchronous read operations.
abstract class Box<E> implements BoxBase<E> {
  /// All the values in the box.
  ///
  /// The values are in the same order as their keys.
  Iterable<E> get values;

  /// Returns an iterable which contains all values starting with the value
  /// associated with [startKey] (inclusive) to the value associated with
  /// [endKey] (inclusive).
  ///
  /// If [startKey] does not exist, an empty iterable is returned. If [endKey]
  /// does not exist or is before [startKey], it is ignored.
  ///
  /// The values are in the same order as their keys.
  Iterable<E> valuesBetween({dynamic startKey, dynamic endKey});

  /// Returns the value associated with the given [key]. If the key does not
  /// exist, `null` is returned.
  ///
  /// If [defaultValue] is specified, it is returned in case the key does not
  /// exist.
  E? get(dynamic key, {E? defaultValue});

  /// Returns the value associated with the n-th key.
  E? getAt(int index);

