11	/// The Insertion Modal — a 3-tab bottom sheet (Texto/Áudio/Foto) opened
12	/// from the Home/Chat "+" control (`placeholder_screens.dart`). Only
13	/// Texto is functional this story (Boundaries) — Áudio/Foto each render
14	/// their own idle, non-interactive placeholder (Stories 3.2/3.3).
15	class InsertionModal extends StatelessWidget {
16	  const InsertionModal({required this.cubit, super.key});
17	
18	  final TextEntryCubit cubit;
19	
20	  /// Presents the modal exactly as the Boundaries dictate:
21	  /// `showModalBottomSheet(isScrollControlled: true, barrierColor:
22	  /// colorScrimHeavy)`, `radiusLg` top corners + `elevation2` (drawn by
23	  /// this widget's own `Container`, not Material's `elevation` double —
24	  /// same convention `ConfirmationDialog`'s card already uses), and a
25	  /// `durationSheetUp` entrance that collapses to zero under Reduce
26	  /// Motion (`MediaQuery.disableAnimations`).
27	  ///
28	  /// [cubit] is a fresh, `get_it`-factory-scoped instance — one per "+"
29	  /// tap (Boundaries: "Modal open resets"), closed here once the sheet is
30	  /// gone, regardless of how it closed (Salvar success, "x", swipe-down,
31	  /// or barrier dismiss) — the caller never has to remember to do this
32	  /// itself.
33	  static Future<void> show(
34	    BuildContext context, {
35	    required TextEntryCubit cubit,
36	  }) async {
37	    final reduceMotion = MediaQuery.of(context).disableAnimations;
38	    final controller =
39	        BottomSheet.createAnimationController(Navigator.of(context))
40	          ..duration = reduceMotion
41	              ? Duration.zero
42	              : DesignTokens.durationSheetUp;
43	    try {
44	      await showModalBottomSheet<void>(
45	        context: context,
46	        isScrollControlled: true,
47	        barrierColor: DesignTokens.colorScrimHeavy,
48	        backgroundColor: Colors.transparent,
49	        elevation: 0,
50	        transitionAnimationController: controller,
51	        builder: (_) => InsertionModal(cubit: cubit),
52	      );
53	    } finally {
54	      // `showModalBottomSheet`'s own Future completes as soon as the
55	      // route is popped — *before* the exit (`reverse()`) animation the
56	      // framework drives on this same controller actually finishes.
57	      // Disposing immediately would cancel that animation's ticker
58	      // mid-flight, permanently freezing the sheet on screen (its
59	      // `AnimatedBuilder` keeps rendering the controller's last value,
60	      // and the route itself never reaches `AnimationStatus.dismissed`
61	      // to be removed from the `Overlay`). Documented behavior
62	      // (`BottomSheet.transitionAnimationController`'s own doc: "the
63	      // caller is responsible for disposing it when the controller is
64	      // no longer needed") — waiting for `dismissed` first is that
65	      // "no longer needed" point.
66	      if (!controller.isDismissed) {
67	        final animationDone = Completer<void>();
68	        void onStatusChange(AnimationStatus status) {
69	          if (status == AnimationStatus.dismissed) {
70	            animationDone.complete();
71	          }
72	        }
73	
74	        controller.addStatusListener(onStatusChange);
75	        await animationDone.future;
76	        controller.removeStatusListener(onStatusChange);
77	      }
78	      controller.dispose();
79	      await cubit.close();
80	    }

